echo '' | base64 -d > /tmp/kd.php; docker cp /tmp/kd.php filenest-app:/tmp/x.php; rm /tmp/kd.php
docker exec -u www-data -w /var/www/html filenest-app php -r "require 'vendor/autoload.php'; \$app = require 'bootstrap/app.php'; \$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); require '/tmp/x.php';" 2>&1 | head -20
docker exec filenest-app rm -f /tmp/x.php
docker exec filenest-app sh -c 'grep -h "Koha\|koha" /var/www/html/storage/logs/laravel*.log 2>/dev/null | tail -5 | cut -c1-400'
